import { isValidObjectId } from "mongoose";
import { Fair } from "../../Models/fair.model.js";

export const addFair = async (req, res) => {
  try {
    const { from, to, price, vehicle } = req.body;

    // Validation (use 400 for bad request)
    if (!from) {
      return res.status(400).json({
        message: "Enter Destination From",
        success: false,
      });
    } else if (!to) {
      return res.status(400).json({
        message: "Enter Destination To",
        success: false,
      });
    } else if (!price) {
      return res.status(400).json({
        message: "Enter price",
        success: false,
      });
    } else if (!vehicle) {
      return res.status(400).json({
        message: "Select Vehicle",
        success: false,
      });
    }
    const data = { from, to, price, vehicle }

    // Save to database
    const response = new Fair(data);
    await response.save();

    return res.status(200).json({
      message: "Fair added successfully",
      success: true,
      data: response
    });

  } catch (error) {
    console.error("Error while adding fair:", error);
    return res.status(500).json({
      message: "Error while adding fair",
      success: false,
      error: error.message,
    });
  }
};


export const viewFair = async (req, res) => {
  try {
    const { id } = req.params;
    if (!isValidObjectId(id)) {
      return res.status(404).json({
        message: "Invalid Id",
        success: false
      })
    }
    // const response = await Fair.findById(id).populate('from').populate('to').populate('vehicle');
    const response = await Fair.findById(id).populate('from', 'address').populate('to', 'address').populate('vehicle', 'name');
    return res.status(200).json({
      message: "View Fair Data",
      success: true,
      data: response
    })
  } catch (error) {
    console.log(error);
    return res.status(404).json({
      message: "Error while viewing fair",
      success: false
    })
  }
}

export const deleteFair = async (req, res) => {
  try {
    const { id } = req.params;
    if (!isValidObjectId(id)) {
      return res.status(404).json({
        message: "Invalid Id",
        success: false,
      })
    }
    const operation = await Fair.findById(id)
    if (!operation) {
      return res.status(404).json({
        message: "Data not exist in DB",
        success: false,
      })
    } else {
      await Fair.deleteOne(operation);
      return res.status(200).json({
        message: "Fair deleted Successfully",
        success: true
      })
    }

  } catch (error) {
    console.log(error);
    return res.status(404).json({
      message: "Error while delete Fair",
      success: false,
      error: error.message
    })
  }
}


