export const editFairById = async (req, res) => {
  try {
    const { id } = req.params;
    if (!isValidObjectId(id)) {
      return res.status(404).json({
        message: "Invalid Id",
        success: false
      })
    }
    const operation = await Fair.findById(id);
    const data = {
      price: req.body.price
    }
    if (!operation) {
      return res.status(404).json({
        message: "Data not exist in Database",
        success: false
      })
    } else {
      const response = await Fair.updateOne(data);
      return res.status(200).json({
        message: "Edit Fair Data",
        success: true,
        data: response
      })
    }
  } catch (error) {
    console.log(error);
    return res.status(404).json({
      message: "Error while editing fair",
      success: false,
      error: error.message
    })
  }
}


